{
  "findings": [
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_iam_role.pass1",
      "severity": "MEDIUM",
      "explanation": "The IAM role defined in this file is not attached to any EC2 instance. Without attaching the role, it cannot be used to grant permissions to an EC2 instance, which may lead to misconfigured or non-functional access."
    }
  ],
  "patched_code": "resource "aws_iam_role" "pass1" {
  name                = "pass1"
  assume_role_policy  = data.aws_iam_policy_document.instance_assume_role_policy.json
  managed_policy_arns = ["arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"]
}

resource "aws_instance" "example" {
  ami           = "ami-12345678"
  instance_type = "t2.micro"

  iam_instance_profile = aws_iam_instance_profile.pass1_profile.name
}

resource "aws_iam_instance_profile" "pass1_profile" {
  name = "pass1_profile"
  role = aws_iam_role.pass1.name
}",
  "fix_summary": "Added an EC2 instance and an IAM instance profile to attach the IAM role to an EC2 instance, ensuring the role can be used as intended."
}
